<?php declare(strict_types=1); ?><!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Kullanıcı yönetimi</title><style>body{font-family:system-ui;background:#f5f7f5;color:#26332b;margin:0}.wrap{max-width:1100px;margin:35px auto;padding:0 18px}table{width:100%;border-collapse:collapse;background:white;border-radius:14px;overflow:hidden}td,th{text-align:left;padding:13px;border-bottom:1px solid #edf0ed;font-size:14px}button{border:0;background:#176b50;color:white;padding:9px 12px;border-radius:8px;font-weight:700}.muted{color:#6d796f;font-size:12px}
/* Consistent admin links and actions */
a{color:#176b50;text-decoration:none;transition:color .18s ease,background-color .18s ease,border-color .18s ease}a:hover{color:#104c39;text-decoration:none}td a:not([class]),.table-wrap a:not([class]){display:inline-flex;align-items:center;justify-content:center;padding:7px 11px;border:1px solid #dce9e0;border-radius:8px;background:#f5faf6;color:#176b50;font-size:12px;font-weight:750;white-space:nowrap}td a:not([class]):hover,.table-wrap a:not([class]):hover{background:#eaf4ee;border-color:#b9d8c4}button,input[type=submit]{cursor:pointer;font:inherit}button{transition:filter .18s ease,transform .18s ease}button:hover,input[type=submit]:hover{filter:brightness(.96)}
</style></head><body><main class="wrap"><h1>Kullanıcılar</h1><?php if(($_GET['role_updated']??'')==='1'): ?><p role="status" style="padding:12px 15px;background:#eaf4ee;color:#176b50;border-radius:9px">Kullanıcı rolü güncellendi; eski oturumları kapatıldı.</p><?php endif; ?><?php if(($_GET['deleted']??'')==='1'): ?><p role="status" style="padding:12px 15px;background:#eaf4ee;color:#176b50;border-radius:9px">Üye hesabı silindi. Geçmiş rezervasyon kayıtları korundu.</p><?php endif; ?><table><thead><tr><th>Kullanıcı</th><th>E-posta</th><th>Rol</th><th>Durum</th><th>Kayıt</th><th>İşlemler</th></tr></thead><tbody><?php foreach($users as $account): ?><tr><td><?= e($account['username']) ?></td><td><?= e($account['email']) ?></td><td><?= e($account['role']) ?><?php if(($currentUser['role']??'')==='super_admin' && (int)$account['id']!==(int)$currentUser['id'] && $account['role']!=='super_admin'): ?><form method="post" action="/admin/users/role" style="margin-top:7px"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$account['id'] ?>"><select name="role" aria-label="Yeni rol" style="max-width:130px;padding:6px;border:1px solid #dce4dc;border-radius:7px"><?php foreach(['admin'=>'Yönetici','editor'=>'Editör','support'=>'Destek','customer'=>'Müşteri','vendor'=>'Ev sahibi'] as $roleValue=>$roleLabel): ?><option value="<?= e($roleValue) ?>" <?= $account['role']===$roleValue?'selected':'' ?>><?= e($roleLabel) ?></option><?php endforeach; ?></select><button type="submit" style="padding:6px 8px;margin-top:5px">Rolü kaydet</button></form><?php endif; ?></td><td><?= e($account['status']) ?></td><td class="muted"><?= e($account['created_at']) ?></td><td><?php if((int)$account['id']!==(int)$currentUser['id'] && \App\Core\Auth::canManageUserRole((string)$currentUser['role'], (string)$account['role'])): ?><form method="post" action="/admin/users/status" style="display:inline-block;margin:0 6px 6px 0"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$account['id'] ?>"><input type="hidden" name="status" value="<?= $account['status']==='active'?'disabled':'active' ?>"><button><?= $account['status']==='active'?'Devre dışı bırak':'Etkinleştir' ?></button></form><?php if(in_array($account['role'],['customer','vendor'],true)): ?><form method="post" action="/admin/users/delete" style="display:inline-block;margin:0 0 6px" onsubmit="return confirm('Bu üyeyi silmek istediğinize emin misiniz? Geçmiş rezervasyonları korunur ancak hesap kalıcı olarak silinir.')"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$account['id'] ?>"><button type="submit" style="background:#b42318">Üyeyi sil</button></form><?php endif; ?><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></main></body></html>